<script setup lang="ts">
import {computed,nextTick,watch} from 'vue';import hljs from 'highlight.js/lib/core';import python from 'highlight.js/lib/languages/python';import {useWorkbench} from '../stores/workbench';import {downloadText} from '../api/client';import {ElMessage} from 'element-plus';hljs.registerLanguage('python',python);const s=useWorkbench();const blocks=computed(()=>{const lines=(s.artifacts?.code||'').split('\n');const out:any[]=[];let b:any={id:'header',title:'模块与函数入口',start:1,lines:[]};lines.forEach((line:string,i:number)=>{const m=line.match(/#\s*>>>\s*\[([^\]]+)\]\s*(.*)/);if(m){if(b.lines.length)out.push(b);b={id:m[1],title:m[2]||m[1],start:i+1,lines:[]};}b.lines.push(line)});if(b.lines.length)out.push(b);return out;});function highlight(code:string){return hljs.highlight(code,{language:'python'}).value;}async function copy(){try{await navigator.clipboard.writeText(s.artifacts.code);ElMessage.success('代码已复制')}catch{ElMessage.warning('浏览器未允许复制，请下载代码')}}watch(()=>s.focusId,async()=>{await nextTick();document.getElementById('code-'+s.focusId)?.scrollIntoView({behavior:'smooth',block:'center'})},{immediate:true});
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">确定性模板 · 只读代码</div><h2>Pyomo 模型代码</h2></div><div class="actions"><el-button :disabled="!s.artifacts?.code" @click="copy">复制</el-button><el-button :disabled="!s.artifacts?.code" @click="downloadText('model-v'+s.spec.version+'.py',s.artifacts.code)">下载代码</el-button></div></div><template v-if="s.artifacts?.code"><div class="notice">代码与当前确认版本绑定。试构建执行同一份代码，使用 T = 1 且跳过 B9，不调用求解器。</div><details v-for="b in blocks" :key="b.id" :id="'code-'+b.id" :open="s.focusId===b.id||b.id==='header'||blocks.length<5" class="code-block" :class="{focused:s.focusId===b.id,custom:s.spec.structural.some((x:any)=>x.id===b.id&&x.custom_code)}"><summary><span class="spec-id">{{b.id}}</span>{{b.title}}<button v-if="b.id.startsWith('dp-')||b.id.startsWith('s-')" class="text-button" @click.stop.prevent="s.focusId=b.id;s.tab='spec'">定位规格 ↗</button></summary><div class="code-lines"><div v-for="(line,i) in b.lines" :key="i" class="code-line"><span class="line-number">{{b.start+i}}</span><code v-html="highlight(line||' ')"></code></div></div></details></template><el-empty v-else description="确认规格后才生成代码；未确认的推断项不会进入代码。"/></div></template>